 void halt(){guard.stop();if(moving&&phase==3)tx(hex("0301011f0301012303010127"));moving=false;}
 static QByteArray enc(int v,bool neg=false){QByteArray b;int sign=neg?64:0,low=v&127,high=v>>7;if(high==0)b.append(char(low|sign));else if(high<64){b.append(char(128|sign|high));b.append(char(low));}else{b.append(char(128|sign|(high>>7)));b.append(char(128|(high&127)));b.append(char(low));}return b;}
