 void handshake(){phase=1;rx.clear();feedbackBuffer.clear();lastPosition.clear();QByteArray b="DORIC\n";b+=hex("1b81060220142176358c1ef069ced27be3c1d796929737dbb56b479a29fcea1be6200bccfb202b2f251870aabde90fb7bd0427fe762feba01c4f41dbb48aa6c3e2af3259211002204d5a6de53873433a3088fb770e5651f0b5a5eca3cf7f0845f8d8061fc0382905209bab1c04b4bb64fd14210e47561c87ca88d251ede373fe956452e729e314092c");tx(b);}
 void feedback(QByteArray b){feedbackBuffer+=b;while(!feedbackBuffer.isEmpty()){int n=static_cast<unsigned char>(feedbackBuffer[0]);if(n==0){feedbackBuffer.remove(0,1);continue;}if(feedbackBuffer.size()<n+1)return;auto p=feedbackBuffer.mid(1,n);feedbackBuffer.remove(0,n+1);if(!p.startsWith(hex("00010a")))continue;int k=3;QByteArray fields[4];bool ok=true;for(auto &field:fields){do{if(k>=p.size()||field.size()>=3){ok=false;break;}field.append(p[k++]);}while(static_cast<unsigned char>(field.back())&128);if(!ok)break;}if(ok&&k==p.size()){lastPosition=hex("010113")+fields[0]+hex("01")+fields[1]+hex("01")+fields[2]+hex("010000");lastPosition.prepend(char(lastPosition.size()));note("Feedback PTZ experimental disponibil");}}} void receive(){auto b=sock.readAll();if(phase==3)feedback(b);note("RX "+b.toHex(' ').toUpper());if(phase!=1)return;rx+=b;if(rx.size()<143)return;if(!rx.startsWith("DORIC")){sock.abort();return;}phase=2;QList<QByteArray> steps{hex("040001010104010101010401010b01"),hex("650001020213")+QByteArray("Precision 60 Camera\"HC9.15.0.11 aec227943ed 2021-01-28\x07targets!102110,102110-1,102110-2,102110-3"),hex("03010116"),hex("03010114"),hex("03010114")};for(int i=0;i<steps.size();++i)QTimer::singleShot(i*180,this,[this,steps,i]{if(phase==2)tx(steps[i]);});QTimer::singleShot(900,this,[this]{if(phase==2){phase=3;handshakeTimer.stop();ready(true);}});}
