 Panel(){auto *outer=new QVBoxLayout(this);outer->setContentsMargins(0,0,0,0);auto *scroll=new QScrollArea(this);scroll->setWidgetResizable(true);outer->addWidget(scroll);auto *body=new QWidget;scroll->setWidget(body);auto *v=new QVBoxLayout(body);v->addWidget(new QLabel("<b>Sab Sound | Cisco PTZ</b>"));ip=new QLineEdit(settings.value("ip","192.168.0.224").toString());trust=new QCheckBox("Accept certificat camera neverificat (LAN privat)");auto *r=new QHBoxLayout;auto *c=new QPushButton("Conectare"),*d=new QPushButton("Deconectare");r->addWidget(c);r->addWidget(d);status=new QLabel;v->addWidget(status);controls=new QWidget;v->addWidget(controls);auto *cl=new QVBoxLayout(controls);cl->setContentsMargins(0,0,0,0);auto *tabs=new QTabWidget;cl->addWidget(tabs);auto *ptzPage=new QWidget;tabs->addTab(ptzPage,"Control");tabs->tabBar()->setExpanding(true);tabs->setUsesScrollButtons(false);auto *cv=new QVBoxLayout(ptzPage);cv->setSpacing(4);cv->setContentsMargins(5,5,5,5);speed=new QSlider(Qt::Horizontal);speed->setRange(1,5);speed->setValue(qBound(1,settings.value("speed",1).toInt(),5));speed->setTickPosition(QSlider::TicksBelow);speed->setTickInterval(1);auto *sl=new QLabel(QString("Viteza PTZ: %1").arg(speed->value()));cv->addWidget(sl);cv->addWidget(speed);connect(speed,&QSlider::valueChanged,this,[this,sl](int n){sl->setText(QString("Viteza PTZ: %1").arg(n));settings.setValue("speed",n);if(moving&&phase==3&&motionPacket.size()>=5){motionPacket[4]=char(n);if(motionPacket.size()==6)motionPacket[5]=char(n);tx(motionPacket);}});auto *g=new QGridLayout;cv->addLayout(g);const char *labels[]={"NW","Sus","NE","Stanga","CENTRU","Dreapta","SW","Jos","SE"};int ops[]={0x1b,0x19,0x1c,0x17,0,0x18,0x1d,0x1a,0x1e};for(int i=0;i<9;i++){auto *b=new QPushButton(labels[i]);b->setStyleSheet(i==4?"QPushButton{background-color:#176b70;color:white;border:1px solid #218a90;border-radius:4px;padding:5px;}QPushButton:hover{background-color:#218a90;}QPushButton:pressed{background-color:#243447;}QPushButton:disabled{background-color:#34383e;color:#888;border-color:#444;}":"QPushButton{background-color:#294c70;color:white;border:1px solid #38658f;border-radius:4px;padding:5px;}QPushButton:hover{background-color:#38658f;}QPushButton:pressed{background-color:#243447;}QPushButton:disabled{background-color:#34383e;color:#888;border-color:#444;}");g->addWidget(b,i/3,i%3);if(i==4)connect(b,&QPushButton::clicked,this,[this]{cmd("0C01011300010001A020010000");});else motion(b,ops[i],i%2==0);}auto *z=new QGridLayout;cv->addLayout(z);const char *ml[]={"Zoom -","Zoom +","Focus Near","Focus Far"};int mo[]={0x22,0x21,0x25,0x26};for(int i=0;i<4;i++){auto *b=new QPushButton(ml[i]);if(i<2)b->setStyleSheet("QPushButton{background-color:#176b70;color:white;border:1px solid #218a90;border-radius:4px;padding:5px;}QPushButton:hover{background-color:#218a90;}QPushButton:pressed{background-color:#243447;}QPushButton:disabled{background-color:#34383e;color:#888;border-color:#444;}");z->addWidget(b,i/2,i%2);motion(b,mo[i]);}auto *presets=new QGridLayout;cv->addWidget(new QLabel("Pozitii memorate"));cv->addLayout(presets);for(int i=1;i<=4;++i){auto key=QString("presetRaw/%1").arg(i);auto *go=new QPushButton(QString("POSITION %1").arg(i));auto *save=new QPushButton(QString("SET %1").arg(i));go->setStyleSheet("QPushButton{background:#294c70;color:white;padding:5px;border-radius:4px;}QPushButton:disabled{background:#34383e;color:#888;}");save->setStyleSheet("QPushButton{background:#286443;color:white;padding:5px;border-radius:4px;}");presets->addWidget(go,i-1,0);presets->addWidget(save,i-1,1);go->setEnabled(!settings.value(key).toByteArray().isEmpty());connect(save,&QPushButton::clicked,this,[this,key,go,i]{if(phase!=3||moving)return;lastPosition.clear();int request=++presetRequest;tx(hex("03010115"));QTimer::singleShot(350,this,[this,key,go,i,request]{if(request!=presetRequest||phase!=3||moving||lastPosition.isEmpty()){note("SET: citirea pozitiei nu a fost confirmata");return;}settings.setValue(key,lastPosition);settings.sync();go->setEnabled(true);note(QString("Preset %1 salvat: %2").arg(i).arg(QString(lastPosition.toHex(' ').toUpper())));});});connect(go,&QPushButton::clicked,this,[this,key]{if(phase!=3)return;auto p=settings.value(key).toByteArray();if(p.isEmpty())return;halt();++presetRequest;lastPosition.clear();tx(p);});}presets->setColumnStretch(0,2);presets->setColumnStretch(1,1);cv->addStretch();auto *settingsPage=new QWidget;tabs->addTab(settingsPage,"Setari");cv=new QVBoxLayout(settingsPage);cv->addWidget(ip);cv->addWidget(trust);cv->addLayout(r);auto *actions=new QGridLayout;cv->addLayout(actions);const char *names[]={"Power ON","Power OFF","LED verde ON","LED verde OFF","Autofocus (test)"};const char *packets[]={"0301012b","0301012c","0401010c00","0401010c01","03010129"};for(int i=0;i<5;i++){auto *b=new QPushButton(names[i]);if(i==4){b->setText("Autofocus");ptzPage->layout()->addWidget(b);}if(i==0||i==2)b->setStyleSheet("QPushButton{background-color:#286443;color:white;border:1px solid #388257;border-radius:4px;padding:5px;}QPushButton:hover{background-color:#388257;}QPushButton:pressed{background-color:#243447;}QPushButton:disabled{background-color:#34383e;color:#888;border-color:#444;}");else if(i==1||i==3)b->setStyleSheet("QPushButton{background-color:#783c42;color:white;border:1px solid #984d55;border-radius:4px;padding:5px;}QPushButton:hover{background-color:#984d55;}QPushButton:pressed{background-color:#243447;}QPushButton:disabled{background-color:#34383e;color:#888;border-color:#444;}");if(i!=4)actions->addWidget(b,i/2,i%2);const char *p=packets[i];connect(b,&QPushButton::clicked,this,[this,p]{cmd(p);});}cv->addStretch();auto *logPage=new QWidget;tabs->addTab(logPage,"Jurnal");cv=new QVBoxLayout(logPage);cv->setSpacing(5);raw=new QLineEdit;raw->setPlaceholderText("HEX DORIC");cv->addWidget(raw);auto *send=new QPushButton("Trimite HEX experimental");cv->addWidget(send);connect(send,&QPushButton::clicked,this,[this]{QString s=raw->text();s.remove(QRegularExpression("[\\s-]"));if(s.isEmpty()||s.size()%2||s.size()>256||s.contains(QRegularExpression("[^0-9a-fA-F]")))return;auto p=QByteArray::fromHex(s.toLatin1());if(p.size()<4||static_cast<unsigned char>(p[0])!=p.size()-1){note("Lungime HEX invalida");return;}if(QMessageBox::question(this,"HEX experimental","Trimit o singura data? Poate modifica starea camerei.")==QMessageBox::Yes){halt();tx(p);}});log=new QPlainTextEdit;log->setReadOnly(true);log->setMinimumHeight(120);log->setMaximumHeight(300);log->setMaximumBlockCount(1500);cv->addWidget(log);auto *save=new QPushButton("Salveaza jurnal");cv->addWidget(save);cv->addStretch();connect(save,&QPushButton::clicked,this,[this]{auto path=QFileDialog::getSaveFileName(this,"Jurnal","DORIC.txt");QFile f(path);if(f.open(QIODevice::WriteOnly))f.write(log->toPlainText().toUtf8());});guard.setSingleShot(false);connect(&guard,&QTimer::timeout,this,[this]{if(moving&&phase==3)tx(motionPacket);else guard.stop();});handshakeTimer.setSingleShot(true);connect(&handshakeTimer,&QTimer::timeout,this,[this]{note("Timeout conectare");sock.abort();});connect(c,&QPushButton::clicked,this,[this]{if(!trust->isChecked()){note("Confirma certificatul neverificat pentru camera din LAN.");return;}halt();sock.abort();phase=0;ready(false);note(QString("Qt runtime: %1").arg(qVersion()));note("Qt plugin paths: "+QCoreApplication::libraryPaths().join("; "));note("TLS backends: "+QSslSocket::availableBackends().join(", "));if(!QSslSocket::supportsSsl()){note("TLS indisponibil: backend Qt lipsa sau incompatibil.");return;}note("TLS backend: "+QSslSocket::activeBackend());settings.setValue("ip",ip->text().trimmed());auto cfg=sock.sslConfiguration();cfg.setProtocol(QSsl::TlsV1_0OrLater);cfg.setPeerVerifyMode(QSslSocket::VerifyNone);sock.setSslConfiguration(cfg);handshakeTimer.start(8000);sock.connectToHostEncrypted(ip->text().trimmed(),13496);});connect(d,&QPushButton::clicked,this,[this]{halt();sock.disconnectFromHost();});connect(&sock,&QSslSocket::encrypted,this,[this]{handshake();});connect(&sock,&QSslSocket::readyRead,this,[this]{receive();});connect(&sock,&QSslSocket::disconnected,this,[this]{phase=0;moving=false;guard.stop();handshakeTimer.stop();ready(false);});connect(&sock,&QSslSocket::errorOccurred,this,[this](auto){note(sock.errorString());guard.stop();moving=false;handshakeTimer.stop();phase=0;ready(false);});connect(qApp,&QGuiApplication::applicationStateChanged,this,[this](Qt::ApplicationState state){if(state!=Qt::ApplicationActive)halt();});ready(false);}
 ~Panel(){halt();sock.flush();sock.disconnectFromHost();}
